<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileAddressJsonAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileAddressJsonAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileAddressJsonAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAddressJson returns null on a freshly created holder.
     */
    public function testAddressJsonNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileAddressJsonAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAddressJsonAssigned());
        $this->assertNull($holder->getAddressJson());
    }
}
class ImplWithUserProfileAddressJsonAttributeHolderUnitTest
{
    use UserProfileAddressJsonAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAddressJsonRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAddressJson();
    }
}
